INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6050, 'social innovation', '/ˈsəʊʃəl ˌɪnəˈveɪʃən/', 'noun', '{"zh-TW":["社會創新"],"en":["new approaches to social challenges that are more effective and sustainable"]}', NULL, 'promote social innovation / social innovation ecosystem / scale social innovation', '[{"en":"Social innovation can address challenges that neither government nor markets solve well.","zh-TW":"社會創新可以解決政府和市場都無法很好解決的挑戰。"},{"en":"The fellowship program supports entrepreneurs engaged in social innovation.","zh-TW":"獎學金計畫支持從事社會創新的創業者。"}]', NULL, NULL, 5, 6050, NULL),
(6051, 'social media', '/ˈsəʊʃəl ˈmiːdiə/', 'noun', '{"zh-TW":["社交媒體"],"en":["websites and apps enabling user interaction and content sharing"]}', NULL, 'post on social media / social media marketing', '[{"en":"Social media marketing has become essential for brands.","zh-TW":"社交媒體行銷已成為品牌的必要手段。"},{"en":"The post went viral on social media overnight.","zh-TW":"這篇帖子在一夜之間在社交媒體上瘋傳。"}]', NULL, NULL, 4, 6051, NULL),
(6052, 'social media marketing', '/ˈsoʊʃəl ˈmiːdiə ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["社群媒體行銷"],"en":["using social media platforms to promote products and engage audiences"]}', NULL, 'social media marketing strategy / social media marketing campaign', '[{"en":"Social media marketing drives brand awareness among younger consumers.","zh-TW":"社群媒體行銷在年輕消費者中提高了品牌知名度。"},{"en":"A consistent social media marketing presence builds trust over time.","zh-TW":"持續的社群媒體行銷存在隨時間建立信任。"}]', '{"noun":"social media marketer"}', NULL, 5, 6052, NULL),
(6053, 'social mobility', '/ˈsəʊʃəl məʊˈbɪlɪti/', 'noun', '{"zh-TW":["社會流動性"],"en":["the movement of individuals between different levels of social hierarchy"]}', NULL, 'upward social mobility / social mobility barriers / improve social mobility', '[{"en":"Education is traditionally seen as the primary driver of social mobility.","zh-TW":"教育傳統上被視為社會流動性的主要驅動力。"},{"en":"Social mobility has stalled in many countries over the past two decades.","zh-TW":"過去二十年，許多國家的社會流動性已陷入停滯。"}]', '{"adjective":"socially mobile"}', NULL, 5, 6053, NULL),
(6054, 'social responsibility', '/ˈsoʊʃəl rɪˌspɒnsɪˈbɪlɪti/', 'noun', '{"zh-TW":["社會責任"],"en":["a company''s commitment to act ethically and contribute to social well-being"]}', NULL, 'fulfill social responsibility / corporate social responsibility', '[{"en":"The company''s social responsibility program funds community schools.","zh-TW":"公司的社會責任計劃為社區學校提供資金。"},{"en":"Consumers increasingly choose brands with strong social responsibility.","zh-TW":"消費者越來越傾向於選擇具有強大社會責任感的品牌。"}]', '{"abbreviation":"CSR"}', NULL, 5, 6054, NULL),
(6055, 'social stratification', '/ˈsəʊʃəl ˌstrætɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["社會分層"],"en":["the hierarchical arrangement of individuals or groups in a society"]}', NULL, 'social stratification system / rigid social stratification / analyze social stratification', '[{"en":"Social stratification affects access to education, healthcare, and opportunity.","zh-TW":"社會分層影響到教育、醫療保健和機會的獲得。"},{"en":"Sociologists study social stratification to understand inequality patterns.","zh-TW":"社會學家研究社會分層以理解不平等模式。"}]', '{"adjective":"socially stratified"}', NULL, 5, 6055, NULL),
(6056, 'socialization', '/ˌsəʊʃəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["社會化"],"en":["the process by which individuals learn the values and norms of their society"]}', NULL, 'primary socialization / secondary socialization / socialization process', '[{"en":"Family is the primary agent of socialization for young children.","zh-TW":"家庭是幼兒社會化的主要媒介。"},{"en":"Schools play a crucial role in the secondary socialization of children.","zh-TW":"學校在兒童的次級社會化中發揮著至關重要的作用。"}]', '{"verb":"socialize","adjective":"socialized"}', NULL, 5, 6056, NULL),
(6057, 'socially responsible investing', '/ˈsoʊʃəli rɪˈspɒnsɪbəl ɪnˈvestɪŋ/', 'noun', '{"zh-TW":["社會責任投資"],"en":["an investment strategy incorporating environmental, social, and governance criteria"]}', NULL, 'adopt socially responsible investing / socially responsible investing fund', '[{"en":"Pension funds increasingly adopt socially responsible investing principles.","zh-TW":"養老基金越來越多地採用社會責任投資原則。"},{"en":"Socially responsible investing excludes companies in tobacco or weapons industries.","zh-TW":"社會責任投資排除了煙草或武器行業的公司。"}]', '{"abbreviation":"SRI","synonym":"ESG investing"}', NULL, 5, 6057, NULL),
(6058, 'society', 'səˈsaɪəti', 'noun', '{"zh-TW":["社會；社團","協會"],"en":["the community of people","an organization"]}', NULL, 'modern society/civil society', '[{"en":"Technology plays a huge role in modern society.","zh-TW":"技術在現代社會中扮演著重要角色。"}]', '{"adjective":"social","adverb":"socially"}', NULL, 3, 6058, NULL),
(6059, 'socioeconomic', '/''səʊsiəʊˌiːkəˌnɒmɪk/', 'adjective', '{"zh-TW":["社會經濟的；社經的"],"en":["relating to or concerned with the interaction of social and economic factors"]}', NULL, 'socioeconomic status / socioeconomic inequality / socioeconomic background', '[{"en":"Students from lower socioeconomic backgrounds often have less access to educational resources.","zh-TW":"來自較低社會經濟背景的學生通常獲得的教育資源較少。"},{"en":"The study examined how socioeconomic factors affect health outcomes in urban communities.","zh-TW":"這項研究考察了社會經濟因素如何影響城市社區的健康結果。"}]', '{"adverb":"socioeconomically","noun":"socioeconomics"}', NULL, 5, 6059, NULL),
(6060, 'soft', '/sɒft/', 'adjective', '{"zh-TW":["軟的；柔和的"],"en":["not hard","gentle"]}', NULL, 'soft skills / software', '[{"en":"Soft skills are as important as technical skills.","zh-TW":"軟實力和技術能力一樣重要。"},{"en":"The soft launch went smoothly.","zh-TW":"軟性上市進行順利。"}]', '{"adjective":"soft","verb":"soften","noun":"software","adverb":"softly"}', NULL, 1, 6060, NULL),
(6061, 'soft loan', '/sɒft loʊn/', 'noun', '{"zh-TW":["優惠貸款；軟貸款"],"en":["a loan with a low interest rate or subsidized terms, typically from a government"]}', NULL, 'apply for a soft loan / soft loan program', '[{"en":"The government offered soft loans to encourage small business investment.","zh-TW":"政府提供優惠貸款以鼓勵小企業投資。"},{"en":"Soft loans are often used to fund infrastructure in developing countries.","zh-TW":"優惠貸款通常用於在發展中國家為基礎設施融資。"}]', NULL, NULL, 3, 6061, NULL),
(6062, 'soft power', '/sɒft ˈpaʊər/', 'noun', '{"zh-TW":["軟實力"],"en":["the ability to influence others through culture, values, and diplomacy rather than force"]}', NULL, 'exercise soft power / soft power strategy / use soft power', '[{"en":"Cultural exports such as films and music are tools of a country''s soft power.","zh-TW":"電影和音樂等文化出口是一個國家軟實力的工具。"},{"en":"Education exchanges build soft power by creating positive relationships with future leaders.","zh-TW":"教育交流通過與未來領導人建立正面關係來增強軟實力。"}]', NULL, NULL, 4, 6062, NULL),
(6063, 'soft skills', '/sɒft skɪlz/', 'noun', '{"zh-TW":["軟技能；軟實力"],"en":["interpersonal and social skills valuable in a work environment"]}', NULL, 'develop soft skills / soft skills training', '[{"en":"Communication and teamwork are essential soft skills.","zh-TW":"溝通和團隊合作是重要的軟技能。"},{"en":"The training program focused on developing soft skills among managers.","zh-TW":"培訓計劃專注於培養管理者的軟技能。"}]', NULL, NULL, 4, 6063, NULL),
(6064, 'software', '/ˈsɒftwɛr/', 'noun', '{"zh-TW":["軟體"],"en":["programs used by a computer"]}', NULL, 'software update / software engineer', '[{"en":"Install the latest software update.","zh-TW":"安裝最新的軟體更新。"},{"en":"She develops educational software.","zh-TW":"她開發教育軟體。"}]', NULL, NULL, 3, 6064, 458),
(6065, 'software as a service', '/ˈsɒftweər æz ə ˈsɜːrvɪs/', 'noun', '{"zh-TW":["軟體即服務"],"en":["a software delivery model where applications are hosted and accessed online"]}', NULL, 'adopt SaaS / SaaS solution / SaaS subscription', '[{"en":"The company switched to a SaaS model to reduce IT overhead.","zh-TW":"公司轉向SaaS模式以降低IT管理費用。"},{"en":"SaaS applications are accessible from any device with internet access.","zh-TW":"SaaS應用程式可從任何有網路連接的設備存取。"}]', '{"abbreviation":"SaaS"}', NULL, 5, 6065, NULL),
(6066, 'software update', '/ˈsɒftwɛər ˈʌpdeɪt/', 'noun', '{"zh-TW":["軟體更新"],"en":["a new version of software to fix bugs or add features"]}', NULL, 'install a software update / automatic software update', '[{"en":"Install the latest software update for improved security.","zh-TW":"安裝最新的軟體更新以提升安全性。"},{"en":"Software updates often include important security patches.","zh-TW":"軟體更新通常包括重要的安全修補程式。"}]', NULL, NULL, 5, 6066, NULL),
(6067, 'soil erosion', '/sɔɪl ɪˈrəʊʒən/', 'noun', '{"zh-TW":["土壤侵蝕"],"en":["the wearing away of topsoil by water, wind, or human activity"]}', NULL, 'prevent soil erosion / soil erosion control / soil erosion damage', '[{"en":"Cover crops reduce soil erosion by protecting bare ground.","zh-TW":"覆蓋作物通過保護裸露地面來減少土壤侵蝕。"},{"en":"Soil erosion reduces agricultural productivity and pollutes waterways.","zh-TW":"土壤侵蝕降低農業生產力並污染水道。"}]', '{"verb":"erode","adjective":"eroded"}', NULL, 4, 6067, NULL),
(6068, 'solar energy', '/ˈsəʊlər ˈɛnərdʒi/', 'noun', '{"zh-TW":["太陽能"],"en":["energy from the sun converted into heat or electricity"]}', NULL, 'generate solar energy / solar energy panel', '[{"en":"The building generates its own electricity using solar energy.","zh-TW":"大樓使用太陽能自行發電。"},{"en":"Solar energy has become increasingly cost-competitive.","zh-TW":"太陽能的成本競爭力越來越強。"}]', NULL, NULL, 4, 6068, NULL),
(6069, 'sole', '/soʊl/', 'adjective', '{"zh-TW":["唯一的；獨有的"],"en":["one and only; exclusive"]}', NULL, 'sole purpose / sole responsibility / sole proprietor', '[{"en":"She is the sole owner of the company.","zh-TW":"她是公司的唯一所有人。"},{"en":"The sole purpose of the meeting was budget approval.","zh-TW":"會議的唯一目的是預算審批。"}]', '{"adjective":"sole","adverb":"solely"}', NULL, 1, 6069, NULL),
(6070, 'sole proprietor', '/soʊl prəˈpraɪɪtər/', 'noun', '{"zh-TW":["獨資企業主"],"en":["a person who owns and operates a business without partners"]}', NULL, 'register as sole proprietor / sole proprietor taxes', '[{"en":"As a sole proprietor, all profits and losses are personal income.","zh-TW":"作為獨資企業主，所有利潤和損失都是個人收入。"},{"en":"A sole proprietor has unlimited personal liability for business debts.","zh-TW":"獨資企業主對商業債務承擔無限個人責任。"}]', NULL, NULL, 5, 6070, NULL),
(6071, 'sole proprietorship', '/soʊl prəˈpraɪɪtərʃɪp/', 'noun', '{"zh-TW":["獨資企業；個人獨資企業"],"en":["a business owned and operated by a single person with unlimited liability"]}', NULL, 'operate as a sole proprietorship / sole proprietorship registration', '[{"en":"A sole proprietorship offers simplicity but involves personal liability.","zh-TW":"獨資企業結構簡單，但涉及個人責任。"},{"en":"Many small business owners start as a sole proprietorship.","zh-TW":"許多小企業主以獨資企業形式起步。"}]', NULL, NULL, 5, 6071, NULL),
(6072, 'sole trader', '/soʊl ˈtreɪdər/', 'noun', '{"zh-TW":["個體戶；自營業者"],"en":["a self-employed person who runs a business as an individual"]}', NULL, 'register as a sole trader / sole trader tax', '[{"en":"As a sole trader, all profits are taxed as personal income.","zh-TW":"作為個體戶，所有利潤作為個人收入徵稅。"},{"en":"A sole trader has full control but unlimited personal liability.","zh-TW":"個體戶擁有完全控制權但承擔無限個人責任。"}]', NULL, NULL, 4, 6072, NULL),
(6073, 'solicit', '/səˈlɪsɪt/', 'verb', '{"zh-TW":["徵求；請求"],"en":["to ask for something earnestly"]}', NULL, 'solicit feedback / solicit bids / solicit opinions', '[{"en":"The company solicited feedback from its customers.","zh-TW":"公司向客戶徵求回饋。"},{"en":"We solicited bids from multiple vendors.","zh-TW":"我們向多家供應商徵求報價。"}]', '{"noun":"solicitation","verb":"solicit"}', NULL, 3, 6073, 721),
(6074, 'solidify', '/səˈlɪdɪfaɪ/', 'verb', '{"zh-TW":["鞏固；使堅固"],"en":["to make or become firm or strong"]}', NULL, 'solidify one''s position / solidify partnerships', '[{"en":"The merger solidified the company''s market position.","zh-TW":"合併鞏固了公司的市場地位。"},{"en":"We aim to solidify our partnerships in the region.","zh-TW":"我們旨在鞏固在該地區的合作夥伴關係。"}]', '{"noun":"solidarity","verb":"solidify","adjective":"solid"}', NULL, 3, 6074, NULL),
(6075, 'solution', 'səˈluːʃən', 'noun', '{"zh-TW":["解決方案；答案","溶液"],"en":["a way of solving a problem","an answer to a question"]}', NULL, 'find a solution/cost-effective solution', '[{"en":"We need a cost-effective solution.","zh-TW":"我們需要一個具有成本效益的解決方案。"}]', '{"verb":"solve","adjective":"solvable"}', NULL, 3, 6075, 217),
(6076, 'solve', '/sɑːlv/', 'verb', '{"zh-TW":["解決；解答"],"en":["to find an answer to a problem"]}', NULL, 'solve a problem / solve an issue / problem-solving', '[{"en":"We need to solve this issue before launch.","zh-TW":"我們需要在上線前解決這個問題。"},{"en":"The team solved the technical challenge quickly.","zh-TW":"團隊很快解決了技術挑戰。"}]', '{"noun":"solution","verb":"solve","adjective":"solvable, unsolved"}', NULL, 2, 6076, NULL),
(6077, 'solvency', '/ˈsɒlvənsi/', 'noun', '{"zh-TW":["償債能力"],"en":["the ability to meet long-term financial obligations"]}', NULL, 'maintain solvency / solvency ratio / test of solvency', '[{"en":"The bank passed the solvency test with comfortable margins.","zh-TW":"銀行以舒適的空間通過了償債能力測試。"},{"en":"Declining sales raised concerns about the firm''s solvency.","zh-TW":"銷售額下降引發了對公司償債能力的擔憂。"}]', '{"adjective":"solvent","antonym":"insolvent"}', NULL, 3, 6077, NULL),
(6078, 'solvency ratio', '/ˈsɒlvənsi ˈreɪʃioʊ/', 'noun', '{"zh-TW":["償付能力比率"],"en":["a measure of a company ability to meet long-term financial obligations"]}', NULL, 'calculate solvency ratio / improve solvency ratio', '[{"en":"A solvency ratio above 20% indicates strong financial health.","zh-TW":"20%以上的償付能力比率表明財務狀況良好。"},{"en":"Regulators require insurance firms to maintain a minimum solvency ratio.","zh-TW":"監管機構要求保險公司維持最低償付能力比率。"}]', NULL, NULL, 5, 6078, NULL),
(6079, 'solvent', '/ˈsɒlvənt/', 'adjective', '{"zh-TW":["有償還能力的；有清償能力的"],"en":["having assets in excess of liabilities; able to pay debts"]}', NULL, 'financially solvent / remain solvent / technically solvent', '[{"en":"A company must remain solvent to avoid entering bankruptcy proceedings.","zh-TW":"公司必須保持償債能力，以避免進入破產程序。"},{"en":"The bank was declared solvent following an independent audit of its balance sheet.","zh-TW":"在對其資產負債表進行獨立審計後，銀行被宣告具有償付能力。"}]', '{"noun":"solvency"}', NULL, 3, 6079, NULL),
(6080, 'somewhat', '/ˈsʌmwɑːt/', 'adverb', '{"zh-TW":["有點；稍微"],"en":["to some extent; a little"]}', NULL, 'somewhat different / somewhat surprising / somewhat difficult', '[{"en":"The results were somewhat disappointing.","zh-TW":"結果有點令人失望。"},{"en":"The process is somewhat more complex than expected.","zh-TW":"這個流程比預期的稍微複雜一些。"}]', '{"adverb":"somewhat"}', NULL, 3, 6080, NULL),
(6081, 'sommelier', '/ˌsɒməˈljeɪ/', 'noun', '{"zh-TW":["侍酒師"],"en":["a wine expert who advises on wine in a restaurant"]}', NULL, 'consult the sommelier / ask the sommelier', '[{"en":"The sommelier recommended a local wine with the fish dish.","zh-TW":"侍酒師推薦了一款配魚料理的當地葡萄酒。"},{"en":"A skilled sommelier enhances the dining experience.","zh-TW":"熟練的侍酒師提升了用餐體驗。"}]', NULL, NULL, 3, 6081, NULL),
(6082, 'son', '/sʌn/', 'noun', '{"zh-TW":["兒子"],"en":["a male child"]}', NULL, 'only son / son-in-law', '[{"en":"His son joined the family business.","zh-TW":"他的兒子加入了家族企業。"},{"en":"My son-in-law works in accounting.","zh-TW":"我的女婿在會計部門工作。"}]', '{"noun":"son"}', NULL, 1, 6082, NULL),
(6083, 'soon', '/suːn/', 'adverb', '{"zh-TW":["很快；不久"],"en":["in a short time"]}', NULL, 'as soon as / sooner or later', '[{"en":"We will launch as soon as possible.","zh-TW":"我們會盡快推出。"},{"en":"Sooner or later, the truth will come out.","zh-TW":"遲早真相會水落石出。"}]', '{"adverb":"soon","adjective":"soon"}', NULL, 1, 6083, NULL),
(6084, 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'adjective', '{"zh-TW":["精密的；複雜的","世故的"],"en":["highly developed and complex","having refined taste"]}', NULL, 'sophisticated technology / sophisticated system / sophisticated approach', '[{"en":"The company uses sophisticated data analytics.","zh-TW":"公司使用精密的數據分析。"},{"en":"This requires a more sophisticated approach.","zh-TW":"這需要更精密的方法。"}]', '{"noun":"sophistication","adjective":"sophisticated"}', NULL, 5, 6084, NULL),
(6085, 'sophistry', '/ˈsɒfɪstri/', 'noun', '{"zh-TW":["詭辯；詭辯術"],"en":["the use of clever but false arguments"]}', NULL, 'engage in sophistry / resort to sophistry / mere sophistry', '[{"en":"His defense relied on sophistry rather than genuine evidence.","zh-TW":"他的辯護依賴詭辯而非真實證據。"},{"en":"The audience quickly saw through the speaker''s sophistry.","zh-TW":"聽眾很快看穿了演講者的詭辯。"}]', '{"noun":"sophist","adjective":"sophistic"}', NULL, 3, 6085, NULL),
(6086, 'sophomore', '/ˈsɒfəmɔːr/', 'noun', '{"zh-TW":["大二學生"],"en":["a second-year student"]}', NULL, 'sophomore year / sophomore album', '[{"en":"She''s a sophomore in college.","zh-TW":"她是大二學生。"},{"en":"His sophomore year was the hardest.","zh-TW":"他的大二是最辛苦的。"}]', NULL, NULL, 3, 6086, NULL),
(6087, 'sorry', '/ˈsɒri/', 'adjective', '{"zh-TW":["抱歉的"],"en":["feeling regret or apology"]}', NULL, 'sorry for / sorry to hear', '[{"en":"I am sorry for the inconvenience.","zh-TW":"很抱歉造成不便。"},{"en":"Sorry to hear about the delay.","zh-TW":"很遺憾聽到延遲的消息。"}]', '{"adjective":"sorry"}', NULL, 2, 6087, NULL),
(6088, 'sort', 'sɔːrt', 'verb', '{"zh-TW":["整理；排序","分類"],"en":["to put in order","to separate into groups"]}', NULL, 'sort files/sort by date', '[{"en":"Please sort the files alphabetically.","zh-TW":"請按字母順序整理文件。"}]', '{"noun":"sort, sorting","adjective":"sorted"}', NULL, 1, 6088, NULL),
(6089, 'sound', '/saʊnd/', 'noun', '{"zh-TW":["【主要意義-名詞】聲音；聲響","【次要意義-形容詞】健全的；穩固的；合理的；可靠的","【次要意義-副詞】徹底地（如 sound asleep）"],"en":["[primary - noun] vibrations that travel through air and are heard","[secondary - adjective] in good condition; reliable and sensible","[secondary - adverb] deeply and completely"]}', NULL, 'sound advice / sound investment / sound asleep / of sound mind', '[{"en":"The board agreed that it was a sound investment decision.","zh-TW":"董事會認為這是一個穩健的投資決定。"},{"en":"The auditor confirmed that the company finances were perfectly sound.","zh-TW":"審計師確認公司財務狀況完全健全。"},{"en":"He was sound asleep when the emergency call came through.","zh-TW":"當緊急電話打來時，他睡得正熟。"}]', '{"adverb":"soundly","noun":"soundness"}', '形容詞 sound = 「穩健的/健全的/合理的」，sound advice（正確建議）、sound investment（穩健投資）、sound judgment（合理判斷）是 TOEIC 財務和管理文章的高頻表達。', 2, 6089, NULL),
(6090, 'soundscape', '/ˈsaʊndˌskeɪp/', 'noun', '{"zh-TW":["音景；聲音環境"],"en":["the sonic environment of a place or piece of music"]}', NULL, 'create a soundscape / immersive soundscape / natural soundscape', '[{"en":"The film''s soundscape was as important as its visual imagery.","zh-TW":"電影的音景與其視覺影像同等重要。"},{"en":"Field recording artists document the disappearing soundscapes of nature.","zh-TW":"田野錄音藝術家記錄著正在消失的自然音景。"}]', NULL, NULL, 4, 6090, NULL),
(6091, 'sour', '/''saʊər/', 'adjective', '{"zh-TW":["酸的；酸味的"],"en":["having an acid taste like lemon or vinegar"]}', NULL, 'sour taste / sour cream / turn sour', '[{"en":"The yogurt had a pleasantly sour taste that balanced the sweetness.","zh-TW":"優格有一種令人愉快的酸味，平衡了甜味。"},{"en":"The unripe mango was too sour to eat on its own.","zh-TW":"這個未熟的芒果太酸，不適合單獨食用。"}]', NULL, NULL, 1, 6091, NULL),
(6092, 'source', '/sɔːrs/', 'noun, verb', '{"zh-TW":["來源；出處","採購；尋找來源"],"en":["a place from which something comes","to obtain from a particular place"]}', NULL, 'reliable source / source of income / source materials', '[{"en":"Tourism is the main source of income for the region.","zh-TW":"旅遊業是該地區的主要收入來源。"},{"en":"We source our materials from local suppliers.","zh-TW":"我們從當地供應商採購材料。"}]', '{"noun":"source","verb":"source, outsource"}', NULL, 2, 6092, NULL),
(6093, 'source of funds', '/sɔːrs əv fʌndz/', 'noun', '{"zh-TW":["資金來源"],"en":["where the money used in a transaction originates from"]}', NULL, 'verify the source of funds / disclose the source of funds', '[{"en":"Banks must verify the source of funds for large transactions.","zh-TW":"銀行必須核實大額交易的資金來源。"},{"en":"A clear source of funds declaration is required for compliance.","zh-TW":"合規要求提供明確的資金來源聲明。"}]', NULL, NULL, 5, 6093, NULL),
(6094, 'sourcing', '/ˈsɔːrsɪŋ/', 'noun', '{"zh-TW":["採購；尋源"],"en":["finding and selecting suppliers for goods or services"]}', NULL, 'strategic sourcing / global sourcing / sourcing process', '[{"en":"The sourcing team identified five potential suppliers for the component.","zh-TW":"採購團隊為該零件識別了五個潛在供應商。"},{"en":"Offshore sourcing reduced material costs by 30%.","zh-TW":"境外採購將材料成本降低了30%。"}]', '{"verb":"source","adjective":"sourced"}', NULL, 3, 6094, NULL),
(6095, 'sourcing strategy', '/ˈsɔːrsɪŋ ˈstrætədʒi/', 'noun', '{"zh-TW":["採購策略"],"en":["a plan for identifying and selecting suppliers for goods or services"]}', NULL, 'develop a sourcing strategy / sourcing strategy review', '[{"en":"The sourcing strategy focused on reducing supplier concentration risk.","zh-TW":"採購策略專注於降低供應商集中風險。"},{"en":"Global sourcing strategies can reduce costs but increase complexity.","zh-TW":"全球採購策略可以降低成本但增加複雜性。"}]', NULL, NULL, 5, 6095, NULL),
(6096, 'souvenir', '/''suːvəˌnɪər/', 'noun', '{"zh-TW":["紀念品"],"en":["a thing kept as a reminder of a person, place, or event visited"]}', NULL, 'buy a souvenir / souvenir shop / collect souvenirs', '[{"en":"She bought a small figurine as a souvenir from Paris.","zh-TW":"她在巴黎買了一個小塑像作為紀念品。"},{"en":"The souvenir shop near the museum sold local handicrafts.","zh-TW":"博物館附近的紀念品店出售當地手工藝品。"}]', NULL, NULL, 3, 6096, NULL),
(6097, 'sovereignty', '/ˈsɒvrənti/', 'noun', '{"zh-TW":["主權；最高統治權"],"en":["the authority of a state to govern itself without interference"]}', NULL, 'national sovereignty / state sovereignty / challenge sovereignty', '[{"en":"National sovereignty limits the ability of international bodies to enforce rules.","zh-TW":"國家主權限制了國際機構執行規則的能力。"},{"en":"The agreement respected the sovereignty of each nation to set its own policies.","zh-TW":"該協議尊重每個國家制定本國政策的主權。"}]', '{"adjective":"sovereign","adverb":"sovereignly"}', NULL, 4, 6097, NULL),
(6098, 'spa', '/''spɑː/', 'noun', '{"zh-TW":["水療中心；溫泉療養地"],"en":["a place with mineral spring water believed to have health-giving properties; a facility for health and beauty treatments"]}', NULL, 'visit a spa / spa treatment / luxury spa', '[{"en":"She booked a spa day to relax after months of hard work.","zh-TW":"她預訂了一天的水療服務，在幾個月辛苦工作後放鬆身心。"},{"en":"The resort''s spa offered massages, facials, and hydrotherapy treatments.","zh-TW":"度假村的水療中心提供按摩、臉部護理和水療治療。"}]', NULL, NULL, 1, 6098, NULL),
(6099, 'space', '/speɪs/', 'noun', '{"zh-TW":["空間；太空"],"en":["an area available for use","the universe beyond Earth"]}', NULL, 'office space / co-working space', '[{"en":"We are looking for new office space.","zh-TW":"我們正在尋找新的辦公空間。"},{"en":"Co-working spaces are popular with startups.","zh-TW":"共同工作空間很受新創公司歡迎。"}]', '{"noun":"space","adjective":"spacious","verb":"space"}', NULL, 2, 6099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6100, 'span', '/spæn/', 'noun, verb', '{"zh-TW":["跨度；時間段","跨越"],"en":["the full extent of something","to extend across"]}', NULL, 'time span / attention span / span a period', '[{"en":"The project spans a period of three years.","zh-TW":"該專案跨越三年時間。"},{"en":"The average attention span is decreasing.","zh-TW":"平均注意力持續時間正在減少。"}]', '{"noun":"span","verb":"span"}', NULL, 1, 6100, NULL),
(6101, 'span of control', '/spæn əv kənˈtroʊl/', 'noun', '{"zh-TW":["管理幅度"],"en":["the number of subordinates a manager directly supervises"]}', NULL, 'widen the span of control / narrow the span of control', '[{"en":"Reducing layers increased the span of control for each manager.","zh-TW":"減少管理層次增加了每位管理者的管理幅度。"},{"en":"A wide span of control requires strong communication and delegation skills.","zh-TW":"寬廣的管理幅度需要強大的溝通和授權技巧。"}]', NULL, NULL, 5, 6101, NULL),
(6102, 'spare', '/sper/', 'adjective, verb', '{"zh-TW":["【主要意義-動詞】省去；免除；撥出（時間）","【次要意義-形容詞】多餘的；備用的；空閒的；瘦的","【次要意義-名詞】備用品；備胎"],"en":["[primary - verb] to make something available; to refrain from harming","[secondary - adjective] extra, not currently in use; lean and thin","[secondary - noun] a spare part or tire"]}', NULL, 'spare time / spare room / spare tire / spare no expense / to spare', '[{"en":"Could you spare a few minutes to review this proposal?","zh-TW":"您能撥出幾分鐘時間審閱這份提案嗎？"},{"en":"We have a spare conference room available on the third floor.","zh-TW":"三樓有一個空餘的會議室可供使用。"},{"en":"The company spared no expense in redesigning the headquarters.","zh-TW":"公司不惜重金重新設計總部。"}]', '{"adverb":"sparingly","adjective":"sparing"}', 'spare 最常見陷阱是形容詞用法「備用的/多餘的」及片語 spare no expense（不惜代價），TOEIC 閱讀中常見描述資源調度或設施的語境。', 2, 6102, NULL),
(6103, 'sparse', '/''spɑːrs/', 'adjective', '{"zh-TW":["稀少的；稀疏的"],"en":["thinly dispersed or scattered; not plentiful or abundant"]}', NULL, 'sparse population / sparse vegetation / sparse data', '[{"en":"The desert is characterized by sparse vegetation and extreme temperatures.","zh-TW":"沙漠的特點是植被稀疏和極端溫度。"},{"en":"Her notes were sparse and failed to capture all the important points from the lecture.","zh-TW":"她的筆記很稀少，未能記錄講座中所有的重要觀點。"}]', '{"adverb":"sparsely","noun":"sparseness"}', NULL, 2, 6103, NULL),
(6104, 'speak', '/spiːk/', 'verb', '{"zh-TW":["說話；發言"],"en":["to talk","to address an audience"]}', NULL, 'speak up / so to speak', '[{"en":"Please speak up if you disagree.","zh-TW":"如果不同意請大聲說出來。"},{"en":"She will speak at the conference.","zh-TW":"她將在會議上演講。"}]', '{"verb":"speak","noun":"speaker","noun2":"speech"}', NULL, 2, 6104, NULL),
(6105, 'special purpose vehicle', '/ˈspeʃəl ˈpɜːrpəs ˈviːɪkəl/', 'noun', '{"zh-TW":["特殊目的公司"],"en":["a separate legal entity created for a specific financial transaction or project"]}', NULL, 'set up a special purpose vehicle / special purpose vehicle structure', '[{"en":"The real estate fund used a special purpose vehicle for each property.","zh-TW":"房地產基金為每個物業使用了一個特殊目的公司。"},{"en":"A special purpose vehicle isolates financial risk from the parent company.","zh-TW":"特殊目的公司將財務風險從母公司中隔離出來。"}]', '{"abbreviation":"SPV"}', NULL, 5, 6105, NULL),
(6106, 'specialist', '/ˈspeʃəlɪst/', 'noun', '{"zh-TW":["專家；專業人員"],"en":["a person with expert knowledge in a particular field"]}', NULL, 'HR specialist / marketing specialist / technical specialist', '[{"en":"The company hired a cybersecurity specialist to strengthen its defenses.","zh-TW":"公司聘請了網路安全專家加強防禦。"},{"en":"She became a specialist in supply chain optimization.","zh-TW":"她成為供應鏈優化方面的專家。"}]', '{"plural":"specialists","adjective":"specialized"}', NULL, 4, 6106, NULL),
(6107, 'specialist referral', '/ˈspɛʃəlɪst rɪˈfɜːrəl/', 'noun', '{"zh-TW":["專科轉診"],"en":["a recommendation to see a specialist doctor"]}', NULL, 'obtain a specialist referral / specialist referral letter', '[{"en":"She obtained a specialist referral to see a cardiologist.","zh-TW":"她獲得了轉診心臟科專科醫生的推介信。"},{"en":"Insurance may require a specialist referral before coverage applies.","zh-TW":"保險可能要求專科轉診後才提供承保。"}]', NULL, NULL, 5, 6107, NULL),
(6108, 'specialty', '/ˈspɛʃəlti/', 'noun', '{"zh-TW":["特色菜；招牌菜"],"en":["a food item for which a place is particularly known"]}', NULL, 'house specialty / regional specialty', '[{"en":"The lobster bisque is the restaurant''s specialty.","zh-TW":"龍蝦濃湯是餐廳的招牌菜。"},{"en":"Try the local specialty when visiting a new city.","zh-TW":"造訪新城市時嘗試當地特色菜。"}]', '{"adjective":"special"}', NULL, 3, 6108, NULL),
(6109, 'species extinction', '/ˈspiːʃiːz ɪkˈstɪŋkʃən/', 'noun', '{"zh-TW":["物種滅絕"],"en":["the dying out of a species of plant or animal"]}', NULL, 'prevent species extinction / species extinction crisis / rate of species extinction', '[{"en":"Human activity is driving species extinction at an alarming rate.","zh-TW":"人類活動正在以令人震驚的速度推動物種滅絕。"},{"en":"Species extinction reduces biodiversity and weakens ecosystem functions.","zh-TW":"物種滅絕降低生物多樣性並削弱生態系統功能。"}]', '{"verb":"extinguish","adjective":"extinct"}', NULL, 5, 6109, NULL),
(6110, 'specific', '/spɪˈsɪfɪk/', 'adjective', '{"zh-TW":["具體的；明確的","特定的"],"en":["clearly defined or identified","particular"]}', NULL, 'specific requirements / specific details / industry-specific', '[{"en":"Please provide specific examples.","zh-TW":"請提供具體的例子。"},{"en":"The instructions are very specific.","zh-TW":"指示非常明確。"}]', '{"noun":"specification, specifics","adjective":"specific","adverb":"specifically"}', NULL, 3, 6110, NULL),
(6111, 'specification', '/ˌspesɪfɪˈkeɪʃn/', 'noun', '{"zh-TW":["規格；規範"],"en":["a detailed description of requirements"]}', NULL, 'technical specifications / meet specifications / product specifications', '[{"en":"The product must meet the client''s specifications.","zh-TW":"產品必須符合客戶的規格。"},{"en":"Please review the technical specifications document.","zh-TW":"請審閱技術規格文件。"}]', '{"noun":"specification","verb":"specify","adjective":"specific"}', NULL, 5, 6111, 459),
(6112, 'specify', '/ˈspesɪfaɪ/', 'verb', '{"zh-TW":["指定；詳細說明"],"en":["to state explicitly or in detail"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'specify requirements / as specified / specify the terms', '[{"en":"The contract specifies the delivery date.","zh-TW":"合約中明確指定了交貨日期。"},{"en":"Please specify your preferred payment method.","zh-TW":"請指定您偏好的付款方式。"}]', '{"noun":"specification","verb":"specify","adjective":"specific, specified"}', NULL, 3, 6112, 218),
(6113, 'spectator', '/ˈspɛkteɪtər/', 'noun', '{"zh-TW":["觀眾；旁觀者"],"en":["a person who watches a game or event"]}', NULL, 'spectator sport / thousands of spectators', '[{"en":"Thousands of spectators filled the stadium.","zh-TW":"數千名觀眾坐滿了體育場。"},{"en":"Football is a popular spectator sport.","zh-TW":"足球是一項受歡迎的觀賞性運動。"}]', NULL, NULL, 3, 6113, NULL),
(6114, 'spectator sport', '/''spekteɪtər spɔːrt/', 'noun', '{"zh-TW":["觀賞性運動；觀眾運動"],"en":["a sport that attracts a large number of spectators to watch"]}', NULL, 'popular spectator sport / major spectator sport', '[{"en":"Soccer is the most popular spectator sport in the world.","zh-TW":"足球是世界上最受歡迎的觀賞性運動。"},{"en":"The stadium holds eighty thousand fans, making it ideal for large spectator sports.","zh-TW":"球場可容納八萬名球迷，使其成為大型觀賞性運動的理想場所。"}]', NULL, NULL, 5, 6114, NULL),
(6115, 'speculate', '/ˈspekjuleɪt/', 'verb', '{"zh-TW":["推測；猜測","投機"],"en":["to form a theory without firm evidence","to invest in risky ventures"]}', NULL, 'speculate on / speculate about / speculate in stocks', '[{"en":"Analysts speculate that the merger will proceed.","zh-TW":"分析師推測合併將繼續進行。"},{"en":"He speculated in the stock market.","zh-TW":"他在股市進行投機。"}]', '{"noun":"speculation, speculator","verb":"speculate","adjective":"speculative"}', NULL, 3, 6115, NULL),
(6116, 'speculation', '/ˌspekjʊˈleɪʃən/', 'noun', '{"zh-TW":["投機；推測"],"en":["the activity of buying assets hoping for profit from short-term price changes"]}', NULL, 'financial speculation / currency speculation / market speculation', '[{"en":"Currency speculation can destabilize a country''s exchange rate.","zh-TW":"貨幣投機可能破壞一個國家匯率的穩定。"},{"en":"The housing bubble was fueled by speculation rather than genuine end-user demand.","zh-TW":"房地產泡沫是由投機而非真實的最終用戶需求推動的。"}]', '{"verb":"speculate","adjective":"speculative","noun2":"speculator"}', NULL, 4, 6116, NULL),
(6117, 'speculative', '/ˈspekjʊlətɪv/', 'adjective', '{"zh-TW":["投機的；推測的"],"en":["based on conjecture rather than knowledge; involving financial speculation"]}', NULL, 'speculative investment / speculative bubble / highly speculative', '[{"en":"Speculative investments in cryptocurrencies resulted in significant losses for many retail investors.","zh-TW":"對加密貨幣的投機性投資給許多散戶投資者造成了重大損失。"},{"en":"The analyst offered a speculative forecast based on limited early data.","zh-TW":"分析師根據有限的早期數據提出了推測性預測。"}]', '{"adverb":"speculatively","verb":"speculate","noun":"speculation"}', NULL, 4, 6117, NULL),
(6118, 'speculative investment', '/ˈspekjʊlətɪv ɪnˈvestmənt/', 'noun', '{"zh-TW":["投機性投資"],"en":["an investment with high risk made in the hope of large returns"]}', NULL, 'make a speculative investment / high-risk speculative investment', '[{"en":"The company avoided speculative investments in favor of stable bonds.","zh-TW":"公司避免了投機性投資，轉而選擇穩定的債券。"},{"en":"Speculative investments can generate high returns but also large losses.","zh-TW":"投機性投資可以帶來高回報，但也可能帶來巨大損失。"}]', NULL, NULL, 5, 6118, NULL),
(6119, 'speech impediment', '/''spiːtʃ ɪmˌpedɪmənt/', 'noun', '{"zh-TW":["語言障礙；口吃"],"en":["a difficulty in speaking that prevents normal fluent communication"]}', NULL, 'overcome a speech impediment / speech impediment treatment / speech impediment therapy', '[{"en":"Speech therapy helped her overcome a speech impediment and gain confidence.","zh-TW":"語言治療幫助她克服了語言障礙，獲得了自信。"},{"en":"Advances in speech therapy have helped many children overcome speech impediments.","zh-TW":"語言治療的進步幫助了許多兒童克服語言障礙。"}]', NULL, NULL, 5, 6119, NULL),
(6120, 'speed', '/spiːd/', 'noun', '{"zh-TW":["速度"],"en":["how fast something moves"]}', NULL, 'at full speed / speed up', '[{"en":"We need to speed up production.","zh-TW":"我們需要加快生產速度。"},{"en":"The project is moving at full speed.","zh-TW":"專案正在全速推進。"}]', '{"noun":"speed","verb":"speed","adjective":"speedy","adverb":"speedily"}', NULL, 2, 6120, NULL),
(6121, 'speed agility quickness', '/''spiːd əˌdʒɪlɪti ˌkwɪknəs/', 'noun', '{"zh-TW":["速度敏捷性訓練"],"en":["a type of training that develops an athlete''s ability to move rapidly and change direction effectively"]}', NULL, 'speed agility quickness training / speed agility quickness drill / speed agility quickness program', '[{"en":"Speed agility quickness drills are fundamental for basketball and soccer players.","zh-TW":"速度敏捷性訓練對籃球和足球運動員至關重要。"},{"en":"The coach incorporated speed agility quickness sessions into the weekly training schedule.","zh-TW":"教練將速度敏捷性訓練課程納入每週訓練計劃。"}]', NULL, NULL, 5, 6121, NULL),
(6122, 'spend', '/spɛnd/', 'verb', '{"zh-TW":["花費；消費"],"en":["to pay money","to use time"]}', NULL, 'spend money / spend time', '[{"en":"We spend 20% of revenue on R&D.","zh-TW":"我們將營收的20%用於研發。"},{"en":"Don''t spend too much time on this.","zh-TW":"不要在這上面花太多時間。"}]', '{"verb":"spend","noun":"spending","noun2":"expenditure"}', NULL, 2, 6122, NULL),
(6123, 'spend analysis', '/spend əˈnæləsɪs/', 'noun', '{"zh-TW":["支出分析"],"en":["reviewing all company purchases to identify savings opportunities"]}', NULL, 'conduct a spend analysis / spend analysis tool', '[{"en":"A spend analysis identified 500000 in potential annual savings.","zh-TW":"支出分析識別了每年50萬元的潛在節省。"},{"en":"Spend analysis is the foundation of a cost reduction initiative.","zh-TW":"支出分析是成本降低計劃的基礎。"}]', NULL, NULL, 5, 6123, NULL),
(6124, 'sphere', '/sfɪr/', 'noun', '{"zh-TW":["領域；範圍","球體"],"en":["an area of activity or influence","a round solid shape"]}', NULL, 'sphere of influence / public sphere / political sphere', '[{"en":"The decision falls within her sphere of influence.","zh-TW":"這個決定屬於她的影響範圍。"},{"en":"The company expanded into new spheres of business.","zh-TW":"公司擴展到新的商業領域。"}]', '{"noun":"sphere","adjective":"spherical"}', NULL, 2, 6124, NULL),
(6125, 'spice', '/''spaɪs/', 'noun', '{"zh-TW":["香料；調味品"],"en":["a strong-flavored or aromatic substance of plant origin used to flavor food"]}', NULL, 'add spice / exotic spice / spice blend', '[{"en":"Turmeric is a spice used widely in South Asian cooking for its color and health benefits.","zh-TW":"薑黃是南亞烹飪中廣泛使用的香料，因其顏色和健康功效而受到重視。"},{"en":"The chef created a unique spice blend that gave the dish a complex, warming flavor.","zh-TW":"廚師調製了獨特的香料混合物，賦予菜肴複雜溫暖的風味。"}]', '{"verb":"spice","adjective":"spicy"}', NULL, 2, 6125, NULL),
(6126, 'spin-off', '/ˈspɪn ɒf/', 'noun', '{"zh-TW":["分拆；子公司獨立上市"],"en":["a new independent company created from a division of an existing company"]}', NULL, 'create a spin-off / spin-off company', '[{"en":"The tech division was spun off as a separate listed company.","zh-TW":"技術部門被分拆為一家獨立的上市公司。"},{"en":"Spin-offs allow each business to pursue strategies more suited to their sector.","zh-TW":"分拆允許每個業務追求更適合其行業的策略。"}]', '{"verb":"spin off"}', NULL, 3, 6126, NULL),
(6127, 'spinoff', '/ˈspɪnɒf/', 'noun', '{"zh-TW":["分拆；衍生公司"],"en":["a new company created by separating part of an existing company"]}', NULL, 'spinoff company / corporate spinoff', '[{"en":"The spinoff allowed each business to focus on its core.","zh-TW":"分拆讓每個業務能夠專注於其核心。"},{"en":"Shareholders received shares in the spinoff entity.","zh-TW":"股東獲得了分拆實體的股份。"}]', '{"verb":"spin off"}', NULL, 3, 6127, NULL),
(6128, 'sponsor', '/ˈspɑːnsər/', 'noun, verb', '{"zh-TW":["贊助者；贊助商","贊助"],"en":["a person or company that pays for an event","to financially support"]}', NULL, 'corporate sponsor / sponsor an event / main sponsor', '[{"en":"The event was sponsored by a major bank.","zh-TW":"活動由一家大型銀行贊助。"},{"en":"We are looking for sponsors for the conference.","zh-TW":"我們正在尋找會議的贊助商。"}]', '{"noun":"sponsor, sponsorship","verb":"sponsor"}', NULL, 3, 6128, 460),
(6129, 'sporadic', '/''spəˈrædɪk/', 'adjective', '{"zh-TW":["零星的；偶發的"],"en":["occurring at irregular intervals or only in a few places; scattered or isolated"]}', NULL, 'sporadic attacks / sporadic growth / sporadic outages', '[{"en":"The company experienced sporadic disruptions to its online service.","zh-TW":"公司對其在線服務經歷了零星的中斷。"},{"en":"Progress was sporadic in the early months, but it accelerated after the first quarter.","zh-TW":"在最初幾個月進展零星，但在第一季度之後加速了。"}]', '{"adverb":"sporadically"}', NULL, 3, 6129, NULL),
(6130, 'sport', '/spɔːrt/', 'verb, noun, adjective', '{"zh-TW":["【主要意義】體育運動；娛樂消遣","【次要意義-動詞】炫耀地穿戴；誇示","【次要意義-名詞】光明磊落的人；有運動精神的人"],"en":["[primary] athletic activity or game","[secondary - verb] to wear or display something proudly or noticeably","[secondary - noun] a person who accepts defeat or teasing cheerfully"]}', NULL, 'sport a new hairstyle / sport a badge / be a good sport', '[{"en":"She sported a brand new designer handbag at the meeting.","zh-TW":"她在會議上炫耀地提著一個全新的設計師手提包。"},{"en":"He was a good sport about losing the competition.","zh-TW":"他輸了比賽後表現得很有運動精神。"},{"en":"The new employee sported a confident smile on his first day.","zh-TW":"新員工在第一天上班時臉上掛著自信的微笑。"}]', '{"noun":"sports, sportsmanship","adjective":"sporting, sporty"}', '動詞用法 sport = 炫耀地展示，常出現在描述外貌或穿著的語境中，TOEIC 閱讀常見陷阱。', 2, 6130, NULL),
(6131, 'sportsmanship', '/''spɔːrtsmənʃɪp/', 'noun', '{"zh-TW":["體育精神；運動精神"],"en":["fair and generous behavior or treatment of others in sports"]}', NULL, 'good sportsmanship / display sportsmanship / exemplary sportsmanship', '[{"en":"Shaking hands after the match is a sign of good sportsmanship.","zh-TW":"比賽後握手是良好體育精神的表現。"},{"en":"The coach emphasized sportsmanship as much as winning.","zh-TW":"教練同樣強調體育精神和獲勝的重要性。"}]', '{"noun":"sportsman"}', NULL, 5, 6131, NULL),
(6132, 'sportsmanship award', '/''spɔːrtsmənʃɪp əˌwɔːrd/', 'noun', '{"zh-TW":["體育精神獎"],"en":["an award given to an athlete who demonstrates exceptional sportsmanship"]}', NULL, 'receive a sportsmanship award / sportsmanship award winner', '[{"en":"He was honored with the tournament''s sportsmanship award for his fair play.","zh-TW":"他因公平競技精神而獲得了錦標賽的體育精神獎。"},{"en":"The sportsmanship award recognizes players who compete with integrity and respect.","zh-TW":"體育精神獎表彰以誠信和尊重競技的球員。"}]', NULL, NULL, 5, 6132, NULL),
(6133, 'spot', '/spɑːt/', 'noun, verb', '{"zh-TW":["地點；位置","發現；注意到"],"en":["a particular place","to notice or identify"]}', NULL, 'on the spot / spot a trend / weak spot', '[{"en":"She spotted an error in the financial report.","zh-TW":"她發現了財務報告中的一個錯誤。"},{"en":"The manager made a decision on the spot.","zh-TW":"經理當場做出了決定。"}]', '{"noun":"spot","verb":"spot"}', NULL, 1, 6133, NULL),
(6134, 'spot price', '/spɒt praɪs/', 'noun', '{"zh-TW":["即期價格；現貨價格"],"en":["the current market price for immediate purchase and delivery"]}', NULL, 'trade at the spot price / spot price volatility', '[{"en":"The spot price of oil rose to 90 dollars per barrel.","zh-TW":"原油即期價格漲至每桶90美元。"},{"en":"Buyers prefer spot price purchases when the market is declining.","zh-TW":"當市場下跌時，買方偏好以即期價格購買。"}]', '{"opposite":"forward price"}', NULL, 4, 6134, NULL),
(6135, 'spot rate', '/spɒt reɪt/', 'noun', '{"zh-TW":["即期匯率；即時利率"],"en":["the current exchange or interest rate for immediate settlement"]}', NULL, 'convert at the spot rate / spot rate fluctuation', '[{"en":"The invoice was converted at the spot rate on the payment date.","zh-TW":"發票在付款日以即期匯率換算。"},{"en":"Currency hedges allow companies to avoid spot rate volatility.","zh-TW":"貨幣對沖允許企業避免即期匯率波動。"}]', NULL, NULL, 3, 6135, NULL),
(6136, 'spread', '/spred/', 'verb, noun', '{"zh-TW":["擴散；傳播","擴展；差價"],"en":["to extend over a larger area","the extent or range of something"]}', NULL, 'spread awareness / spread across / spread the risk', '[{"en":"The company spread its operations across Asia.","zh-TW":"公司將業務擴展至亞洲各地。"},{"en":"We need to spread the investment risk.","zh-TW":"我們需要分散投資風險。"}]', '{"noun":"spread","verb":"spread"}', NULL, 2, 6136, NULL),
(6137, 'sprint', '/sprɪnt/', 'noun', '{"zh-TW":["衝刺；衝刺週期"],"en":["a short, time-boxed period in agile development to complete specific tasks"]}', NULL, 'run a sprint / sprint planning / sprint review / two-week sprint', '[{"en":"Each sprint lasts two weeks in the team''s agile process.","zh-TW":"在團隊的敏捷流程中，每個衝刺持續兩週。"},{"en":"The team completed all sprint goals ahead of schedule.","zh-TW":"團隊提前完成了所有衝刺目標。"}]', '{"verb":"sprint","adjective":"sprint-based"}', NULL, 2, 6137, NULL),
(6138, 'sprint finish', '/''sprɪnt ˌfɪnɪʃ/', 'noun', '{"zh-TW":["最後衝刺"],"en":["a final burst of speed at the end of a race"]}', NULL, 'make a sprint finish / strong sprint finish / impressive sprint finish', '[{"en":"His powerful sprint finish secured first place in the 1500-meter race.","zh-TW":"他強勁的最後衝刺在1500公尺賽跑中確保了第一名。"},{"en":"She was known for her devastating sprint finish in the final hundred meters.","zh-TW":"她因在最後一百公尺的毀滅性最後衝刺而聞名。"}]', NULL, NULL, 5, 6138, NULL),
(6139, 'sprint interval', '/''sprɪnt ˌɪntəvəl/', 'noun', '{"zh-TW":["短跑間歇；衝刺訓練"],"en":["a training method involving short periods of maximum-effort sprinting alternating with rest"]}', NULL, 'do sprint intervals / sprint interval protocol / add sprint intervals', '[{"en":"Sprint intervals improved his running speed more quickly than long-distance training.","zh-TW":"短跑間歇比長距離訓練更快地提高了他的跑步速度。"},{"en":"The training plan includes three sessions of sprint intervals per week.","zh-TW":"訓練計劃包括每週三次短跑間歇訓練。"}]', NULL, NULL, 5, 6139, NULL),
(6140, 'spurious', '/ˈspjʊəriəs/', 'adjective', '{"zh-TW":["偽造的；虛假的"],"en":["not being what it appears to be; false or misleading"]}', NULL, 'spurious correlation / spurious argument / spurious data', '[{"en":"The report excluded spurious data points from the analysis.","zh-TW":"報告從分析中排除了虛假的數據點。"},{"en":"His qualifications were later discovered to be spurious.","zh-TW":"他的資格後來被發現是偽造的。"}]', '{"adverb":"spuriously","noun":"spuriousness"}', NULL, 3, 6140, NULL),
(6141, 'SQL', '/ˌes kjuː ˈel/', 'noun', '{"zh-TW":["銷售合格潛在客戶"],"en":["sales qualified lead; a prospect evaluated as ready for a direct sales approach"]}', NULL, 'convert to SQL / SQL pipeline / track SQLs', '[{"en":"Sales reps focus their efforts on SQLs to maximize conversion.","zh-TW":"銷售代表將精力集中在銷售合格潛在客戶上以最大化轉換。"},{"en":"The SQL rate improved after tightening the qualification criteria.","zh-TW":"收緊資格標準後，銷售合格潛在客戶率有所提高。"}]', '{"full form":"sales qualified lead"}', NULL, 1, 6141, NULL),
(6142, 'squat', '/''skwɒt/', 'noun', '{"zh-TW":["深蹲；蹲"],"en":["an exercise in which you lower the body by bending the knees and hips while keeping the back straight"]}', NULL, 'do squats / squat exercise / barbell squat', '[{"en":"Squats are one of the most effective exercises for strengthening the legs and core.","zh-TW":"深蹲是增強腿部和核心力量最有效的運動之一。"},{"en":"She added one hundred squats to her daily workout routine.","zh-TW":"她在每日鍛煉計劃中增加了一百個深蹲。"}]', '{"verb":"squat"}', NULL, 2, 6142, NULL),
(6143, 'squeeze margin', '/skwiːz ˈmɑːrdʒɪn/', 'verb', '{"zh-TW":["壓縮利潤率"],"en":["to reduce profit margins through rising costs or competitive pricing pressure"]}', NULL, 'squeeze margins / margin squeeze', '[{"en":"Retailers had their margins squeezed by rising logistics costs.","zh-TW":"零售商的利潤率因不斷上升的物流成本而受到壓縮。"},{"en":"Intense competition continued to squeeze margins across the sector.","zh-TW":"激烈的競爭繼續壓縮整個行業的利潤率。"}]', '{"noun":"margin squeeze"}', NULL, 5, 6143, NULL),
(6144, 'stabilize', '/ˈsteɪbəlaɪz/', 'verb', '{"zh-TW":["穩定；使穩定"],"en":["to make or become steady"]}', NULL, 'stabilize prices / stabilize the economy / stabilize the situation', '[{"en":"The government took measures to stabilize the currency.","zh-TW":"政府採取措施穩定貨幣。"},{"en":"Prices have finally stabilized after months of volatility.","zh-TW":"經過數月的波動，價格終於穩定下來。"}]', '{"noun":"stability, stabilization","verb":"stabilize","adjective":"stable"}', NULL, 3, 6144, 722),
(6145, 'stable', '/ˈsteɪbl/', 'adjective', '{"zh-TW":["穩定的；穩固的"],"en":["not likely to change; firmly established"]}', NULL, 'stable economy / stable income / financially stable', '[{"en":"The economy has remained relatively stable.","zh-TW":"經濟保持相對穩定。"},{"en":"A stable income is important for loan approval.","zh-TW":"穩定的收入對貸款審批很重要。"}]', '{"noun":"stability","verb":"stabilize","adjective":"stable, unstable","adverb":"stably"}', NULL, 2, 6145, NULL),
(6146, 'stack overflow', '/stæk ˈəʊvərfləʊ/', 'noun', '{"zh-TW":["堆疊溢出"],"en":["an error that occurs when the call stack exceeds its maximum size"]}', NULL, 'cause a stack overflow / stack overflow error / handle stack overflow', '[{"en":"Recursive functions without proper base cases can cause a stack overflow.","zh-TW":"沒有適當基本案例的遞迴函數可能導致堆疊溢出。"},{"en":"The stack overflow bug was traced to an infinite loop in the parser.","zh-TW":"堆疊溢出錯誤被追蹤到解析器中的無限循環。"}]', NULL, NULL, 5, 6146, NULL),
(6147, 'stadium', '/ˈsteɪdiəm/', 'noun', '{"zh-TW":["體育場"],"en":["a large area for sports events with seats around it"]}', NULL, 'football stadium / stadium tour', '[{"en":"The stadium holds 80,000 people.","zh-TW":"這座體育場可容納八萬人。"},{"en":"The new stadium was built last year.","zh-TW":"新體育場去年建成。"}]', NULL, NULL, 3, 6147, NULL),
(6148, 'staff', '/stæf/', 'noun, verb', '{"zh-TW":["員工；職員","配備人員"],"en":["the people who work for an organization","to provide with workers"]}', NULL, 'staff members / staff training / fully staffed', '[{"en":"All staff must attend the safety briefing.","zh-TW":"所有員工都必須參加安全簡報。"},{"en":"The office is fully staffed during business hours.","zh-TW":"辦公室在營業時間有完整的人員配置。"}]', '{"noun":"staff, staffing","verb":"staff"}', NULL, 2, 6148, 461),
(6149, 'staff productivity', '/stɑːf prəˌdʌkˈtɪvɪti/', 'noun', '{"zh-TW":["員工生產力"],"en":["the output per employee over a given period"]}', NULL, 'measure staff productivity / improve staff productivity', '[{"en":"Flexible work arrangements increased staff productivity.","zh-TW":"彈性工作安排提高了員工生產力。"},{"en":"Staff productivity metrics include output per hour and error rates.","zh-TW":"員工生產力指標包括每小時產出和錯誤率。"}]', NULL, NULL, 5, 6149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6150, 'staff turnover', '/stɑːf ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["員工流動率"],"en":["the rate at which employees leave and are replaced within an organization"]}', NULL, 'reduce staff turnover / high staff turnover', '[{"en":"A high staff turnover is costly and disrupts operations.","zh-TW":"高員工流動率成本高昂並擾亂運營。"},{"en":"Improved working conditions helped reduce staff turnover by 20%.","zh-TW":"改善工作條件幫助將員工流動率降低了20%。"}]', NULL, NULL, 5, 6150, NULL),
(6151, 'staff turnover rate', '/stɑːf ˈtɜːrnoʊvər reɪt/', 'noun', '{"zh-TW":["員工離職率"],"en":["the percentage of employees who leave an organization within a period"]}', NULL, 'reduce staff turnover rate / monitor staff turnover rate', '[{"en":"A high staff turnover rate is costly due to recruitment and training.","zh-TW":"由於招募和培訓成本，高員工離職率代價高昂。"},{"en":"Improving work culture helped lower the staff turnover rate.","zh-TW":"改善工作文化有助於降低員工離職率。"}]', NULL, NULL, 5, 6151, NULL),
(6152, 'staffing', '/ˈstæfɪŋ/', 'noun', '{"zh-TW":["人員配置；招募"],"en":["the process of hiring and placing workers in an organization"]}', NULL, 'staffing agency / staffing levels / staffing needs', '[{"en":"The project required a rapid increase in staffing levels.","zh-TW":"該項目需要迅速增加人員配置。"},{"en":"Staffing agencies provide temporary workers on short notice.","zh-TW":"人力仲介公司能在短時間內提供臨時工作人員。"}]', '{"verb":"staff","noun":"staff"}', NULL, 3, 6152, NULL),
(6153, 'staffing agency', '/ˈstɑːfɪŋ ˈeɪdʒənsi/', 'noun', '{"zh-TW":["人力資源機構；人才派遣機構"],"en":["an organization that provides temporary or permanent workers"]}', NULL, 'hire through a staffing agency / staffing agency contract', '[{"en":"The company used a staffing agency to fill temporary positions.","zh-TW":"公司通過人力資源機構填補臨時職位。"},{"en":"A staffing agency handles recruitment and payroll for temps.","zh-TW":"人力資源機構負責臨時員工的招聘和薪資。"}]', NULL, NULL, 5, 6153, NULL),
(6154, 'stage', '/steɪdʒ/', 'noun, verb', '{"zh-TW":["階段；時期","舉辦；籌劃"],"en":["a point in a process","to organize and present"]}', NULL, 'at this stage / early stage / stage an event', '[{"en":"The project is still in the early stages.","zh-TW":"專案仍處於早期階段。"},{"en":"The company staged a product launch event.","zh-TW":"公司舉辦了一場產品發布活動。"}]', '{"noun":"stage","verb":"stage"}', NULL, 2, 6154, NULL),
(6155, 'stagnant', '/ˈstæɡnənt/', 'adjective', '{"zh-TW":["停滯的；不景氣的"],"en":["showing no activity or growth"]}', NULL, 'stagnant economy / stagnant wages / stagnant market', '[{"en":"Wages have remained stagnant for years.","zh-TW":"薪資已停滯多年。"},{"en":"The stagnant market offers few opportunities.","zh-TW":"停滯的市場提供很少的機會。"}]', '{"noun":"stagnation","verb":"stagnate","adjective":"stagnant"}', NULL, 3, 6155, NULL),
(6156, 'stagnation', '/stæɡˈneɪʃən/', 'noun', '{"zh-TW":["停滯；不景氣"],"en":["a situation characterized by little or no growth or development"]}', NULL, 'economic stagnation / wage stagnation / period of stagnation', '[{"en":"Japan experienced a decade of economic stagnation in the 1990s.","zh-TW":"日本在1990年代經歷了十年的經濟停滯。"},{"en":"Wage stagnation despite rising productivity has increased inequality.","zh-TW":"儘管生產力提高，工資停滯加劇了不平等。"}]', '{"verb":"stagnate","adjective":"stagnant"}', NULL, 4, 6156, NULL),
(6157, 'stake', '/steɪk/', 'noun', '{"zh-TW":["股份；利害關係","賭注"],"en":["a share or interest in a business","something risked"]}', NULL, 'at stake / stakeholder / have a stake in', '[{"en":"Millions of dollars are at stake.","zh-TW":"數百萬美元面臨風險。"},{"en":"She has a 20% stake in the company.","zh-TW":"她擁有公司20%的股份。"}]', '{"noun":"stake, stakeholder"}', NULL, 2, 6157, NULL),
(6158, 'stakeholder', '/ˈsteɪkhoʊldər/', 'noun', '{"zh-TW":["利害關係人"],"en":["a person with an interest or concern in something"]}', NULL, 'key stakeholders / stakeholder engagement / stakeholder management', '[{"en":"All stakeholders were consulted before the decision.","zh-TW":"做決定之前諮詢了所有利害關係人。"},{"en":"Stakeholder engagement is crucial for project success.","zh-TW":"利害關係人參與對專案成功至關重要。"}]', '{"noun":"stakeholder, stake"}', NULL, 4, 6158, 934),
(6159, 'stakeholder analysis', '/ˈsteɪkhoʊldər əˈnæləsɪs/', 'noun', '{"zh-TW":["利害關係人分析"],"en":["a process of identifying and assessing the influence and interests of stakeholders"]}', NULL, 'conduct stakeholder analysis / stakeholder analysis matrix', '[{"en":"A stakeholder analysis was completed at the project initiation stage.","zh-TW":"在項目啟動階段完成了利害關係人分析。"},{"en":"Stakeholder analysis helps prioritize engagement and communication efforts.","zh-TW":"利害關係人分析幫助優先考慮參與和溝通工作。"}]', NULL, NULL, 5, 6159, NULL),
(6160, 'stakeholder capitalism', '/ˈsteɪkˌhəʊldər ˈkæpɪtəlɪzəm/', 'noun', '{"zh-TW":["利益相關者資本主義"],"en":["a model of capitalism in which corporations serve all stakeholders, not just shareholders"]}', NULL, 'embrace stakeholder capitalism / stakeholder capitalism model / debate stakeholder capitalism', '[{"en":"Stakeholder capitalism argues that businesses should balance profits with social and environmental responsibility.","zh-TW":"利益相關者資本主義認為，企業應在利潤與社會及環境責任之間取得平衡。"},{"en":"The Business Roundtable''s 2019 statement endorsed stakeholder capitalism as a guiding corporate principle.","zh-TW":"商業圓桌會議二○一九年的聲明認可了利益相關者資本主義作為指導公司原則。"}]', NULL, NULL, 5, 6160, NULL),
(6161, 'stakeholder communication', '/ˈsteɪkhoʊldər kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["利害關係人溝通"],"en":["the process of keeping all interested parties informed and engaged"]}', NULL, 'improve stakeholder communication / regular stakeholder communication', '[{"en":"Regular stakeholder communication prevents misunderstandings.","zh-TW":"定期的利害關係人溝通防止了誤解。"},{"en":"The project manager sent weekly updates as part of stakeholder communication.","zh-TW":"項目經理作為利害關係人溝通的一部分發送了每週更新。"}]', NULL, NULL, 5, 6161, NULL),
(6162, 'stakeholder engagement', '/ˈsteɪkhoʊldər ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["利害關係人參與"],"en":["the process of involving relevant parties in decision-making"]}', NULL, 'improve stakeholder engagement / stakeholder engagement plan', '[{"en":"Stakeholder engagement ensured the policy change had broad support.","zh-TW":"利害關係人參與確保了政策變更獲得廣泛支持。"},{"en":"A stakeholder engagement plan was developed before the project launched.","zh-TW":"項目啟動前制定了利害關係人參與計劃。"}]', NULL, NULL, 5, 6162, NULL),
(6163, 'stakeholder management', '/ˈsteɪkˌhəʊldər ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["利害關係人管理"],"en":["the process of managing relationships with those affected by a project"]}', NULL, 'effective stakeholder management / stakeholder management plan', '[{"en":"Effective stakeholder management is critical for project success.","zh-TW":"有效的利害關係人管理對項目成功至關重要。"},{"en":"Regular updates are key to good stakeholder management.","zh-TW":"定期更新是良好的利害關係人管理的關鍵。"}]', NULL, NULL, 5, 6163, NULL),
(6164, 'stakeholder meeting', '/''steɪkˌhəʊldər ˌmiːtɪŋ/', 'noun', '{"zh-TW":["利害關係人會議；利益相關者會議"],"en":["a meeting that involves all parties who have an interest in a project or decision"]}', NULL, 'organize a stakeholder meeting / stakeholder meeting agenda / productive stakeholder meeting', '[{"en":"A stakeholder meeting was held to address concerns about the new development project.","zh-TW":"舉行了利害關係人會議，以解決對新開發項目的關切。"},{"en":"Regular stakeholder meetings ensure everyone stays informed and aligned on project goals.","zh-TW":"定期的利害關係人會議確保每個人都了解情況並與項目目標保持一致。"}]', '{"noun":"stakeholder"}', NULL, 5, 6164, NULL),
(6165, 'stakeholder report', '/ˈsteɪkˌhəʊldər rɪˈpɔːrt/', 'noun', '{"zh-TW":["利害關係人報告"],"en":["a report prepared for parties with an interest in an organization"]}', NULL, 'prepare a stakeholder report / distribute stakeholder report', '[{"en":"The annual stakeholder report summarizes company performance.","zh-TW":"年度利害關係人報告總結了公司的表現。"},{"en":"All stakeholder reports must be reviewed by senior management.","zh-TW":"所有利害關係人報告必須由高層管理人員審查。"}]', NULL, NULL, 5, 6165, NULL),
(6166, 'stakeholder value', '/ˈsteɪkhoʊldər ˈvæljuː/', 'noun', '{"zh-TW":["利害關係人價值"],"en":["the benefit delivered to all parties affected by a company''s activities"]}', NULL, 'create stakeholder value / maximize stakeholder value', '[{"en":"A stakeholder value approach considers employees, customers, and communities.","zh-TW":"利害關係人價值方法考慮了員工、客戶和社區。"},{"en":"Companies increasingly report on stakeholder value beyond shareholder returns.","zh-TW":"越來越多的公司報告了股東回報之外的利害關係人價值。"}]', NULL, NULL, 5, 6166, NULL),
(6167, 'stamina', '/''stæmɪnə/', 'noun', '{"zh-TW":["體力；精力；耐力"],"en":["the ability to sustain prolonged physical or mental effort over a long period"]}', NULL, 'build stamina / increase stamina / high stamina', '[{"en":"Cyclists develop exceptional stamina through years of training.","zh-TW":"自行車手通過多年的訓練培養出非凡的體力。"},{"en":"She improved her stamina by gradually increasing her daily run distance.","zh-TW":"她通過逐漸增加每日跑步距離來提高她的體力。"}]', NULL, NULL, 3, 6167, NULL),
(6168, 'stamina building', '/''stæmɪnə ˌbɪldɪŋ/', 'noun', '{"zh-TW":["體力訓練；耐力建設"],"en":["a training approach aimed at developing the ability to sustain prolonged physical effort"]}', NULL, 'focus on stamina building / stamina building exercise / benefit of stamina building', '[{"en":"Long-distance running is one of the most effective stamina building exercises.","zh-TW":"長距離跑步是最有效的體力訓練練習之一。"},{"en":"Her fitness program included stamina building exercises three times per week.","zh-TW":"她的健身計劃每週包含三次體力訓練練習。"}]', NULL, NULL, 5, 6168, NULL),
(6169, 'stamina test', '/''stæmɪnə test/', 'noun', '{"zh-TW":["耐力測試；體力測試"],"en":["a physical assessment designed to measure how long a person can sustain effort"]}', NULL, 'pass a stamina test / fail the stamina test / undergo a stamina test', '[{"en":"Firefighters must pass a stamina test before being certified for field duty.","zh-TW":"消防員在獲得野外任務認證之前必須通過耐力測試。"},{"en":"The stamina test showed that she had significantly improved her aerobic capacity.","zh-TW":"耐力測試顯示她的有氧能力已顯著提升。"}]', NULL, NULL, 4, 6169, NULL),
(6170, 'stamp duty', '/''stæmp ˌdjuːti/', 'noun', '{"zh-TW":["印花稅"],"en":["a government tax on the purchase of real estate, calculated as a percentage of the property value"]}', NULL, 'pay stamp duty / stamp duty exemption / stamp duty rate', '[{"en":"Stamp duty adds a significant cost to buying property, especially for first-time buyers.","zh-TW":"印花稅為購買房產增加了可觀的成本，特別是對首次購房者而言。"},{"en":"The government exempted first-time buyers from stamp duty below a certain threshold.","zh-TW":"政府免除了低於特定門檻的首次購房者的印花稅。"}]', NULL, NULL, 4, 6170, NULL),
(6171, 'stand', '/stænd/', 'verb', '{"zh-TW":["【主要意義-動詞】站立","【次要意義-動詞】忍受；容忍","【次要意義-名詞】立場；態度；主張","【次要意義-名詞】攤位；展台；貨架"],"en":["[primary] to be in an upright position","[secondary - verb] to tolerate or endure without objection","[secondary - noun] a position or attitude toward an issue","[secondary - noun] a small structure where things are sold or displayed"]}', NULL, 'take a stand / stand firm / stand for / exhibition stand / music stand', '[{"en":"The company took a firm stand against using suppliers with poor labor practices.","zh-TW":"公司對使用勞動條件惡劣的供應商採取了堅定的立場。"},{"en":"Our products will be displayed at Stand 24B at the trade fair.","zh-TW":"我們的產品將在貿易展覽會的24B號攤位展出。"},{"en":"I cannot stand the way the new system slows down productivity.","zh-TW":"我無法忍受新系統降低生產力的方式。"}]', '{"noun":"standpoint, standstill","adjective":"outstanding"}', 'stand 作動詞表「忍受」，作名詞表「立場」或「展台攤位」，TOEIC 展覽/貿易類文章常見 stand（攤位），take a stand（表明立場）出現在商業決策文章中。', 2, 6171, NULL),
(6172, 'standalone', '/ˈstænəloʊn/', 'adjective', '{"zh-TW":["獨立的；自立的"],"en":["operating independently without relying on other systems or entities"]}', NULL, 'standalone entity / standalone business / standalone solution', '[{"en":"The division was spun off as a standalone business.","zh-TW":"該部門被分拆為一個獨立業務。"},{"en":"A standalone software system runs without requiring other applications.","zh-TW":"獨立的軟件系統在不需要其他應用程序的情況下運行。"}]', NULL, NULL, 4, 6172, NULL),
(6173, 'standard', '/ˈstændərd/', 'noun, adjective', '{"zh-TW":["標準；水準","標準的；普通的"],"en":["a level of quality","usual or normal"]}', NULL, 'industry standard / standard procedure / set a standard', '[{"en":"Our products meet international quality standards.","zh-TW":"我們的產品符合國際品質標準。"},{"en":"This is standard procedure for all new hires.","zh-TW":"這是所有新進員工的標準程序。"}]', '{"noun":"standard, standardization","verb":"standardize","adjective":"standard"}', NULL, 3, 6173, 219),
(6174, 'standard deviation', '/ˈstændərd ˌdiːviˈeɪʃən/', 'noun', '{"zh-TW":["標準差"],"en":["a statistical measure of the dispersion of data values from the mean"]}', NULL, 'calculate standard deviation / high standard deviation', '[{"en":"A low standard deviation indicates consistent performance.","zh-TW":"低標準差表明績效一致。"},{"en":"Risk analysts use standard deviation to measure investment volatility.","zh-TW":"風險分析師使用標準差來衡量投資波動性。"}]', NULL, NULL, 5, 6174, NULL),
(6175, 'standard operating procedure', '/ˈstændərd ˈɒpəreɪtɪŋ prəˈsiːdʒər/', 'noun', '{"zh-TW":["標準作業程序"],"en":["a documented set of instructions for performing routine operations"]}', NULL, 'follow the SOP / write an SOP / update the SOP', '[{"en":"The standard operating procedure ensures consistent product quality.","zh-TW":"標準作業程序確保一致的產品品質。"},{"en":"New employees are trained on the standard operating procedures.","zh-TW":"新員工接受標準作業程序培訓。"}]', '{"abbreviation":"SOP","plural":"SOPs"}', NULL, 5, 6175, NULL),
(6176, 'standardization', '/ˌstændərdɪˈzeɪʃən/', 'noun', '{"zh-TW":["標準化"],"en":["the process of establishing uniform specifications or methods"]}', NULL, 'pursue standardization / standardization of processes', '[{"en":"Standardization of forms reduced administrative errors by 20%.","zh-TW":"表格的標準化將行政錯誤減少了20%。"},{"en":"Product standardization simplifies manufacturing and reduces costs.","zh-TW":"產品標準化簡化了製造並降低了成本。"}]', '{"verb":"standardize","adjective":"standardized"}', NULL, 5, 6176, 622),
(6177, 'standardize', 'ˈstændərdaɪz', 'verb', '{"zh-TW":["標準化；統一","規範化"],"en":["to make uniform","to apply a standard"]}', NULL, 'standardize processes/standardize formats', '[{"en":"We need to standardize the reporting format.","zh-TW":"我們需要標準化報告格式。"}]', '{"noun":"standardization","adjective":"standardized"}', NULL, 4, 6177, NULL),
(6178, 'standardized test', '/''stændədaɪzd test/', 'noun', '{"zh-TW":["標準化測驗；統一考試"],"en":["a test administered and scored in a consistent, standardized manner to measure knowledge or skills"]}', NULL, 'take a standardized test / prepare for a standardized test / standardized test score', '[{"en":"SAT and ACT are standardized tests used for university admissions in the United States.","zh-TW":"SAT和ACT是美國用於大學入學的標準化測驗。"},{"en":"Critics argue that standardized tests do not fully reflect a student''s potential.","zh-TW":"批評者認為標準化測驗不能完全反映學生的潛力。"}]', NULL, NULL, 5, 6178, NULL),
(6179, 'standardized testing', '/''stændərdaɪzd ˌtestɪŋ/', 'noun', '{"zh-TW":["標準化測驗"],"en":["assessment administered and scored in a consistent, predetermined way across all test-takers"]}', NULL, 'prepare for standardized testing / standardized testing requirements / standardized testing criticism', '[{"en":"Many universities rely on standardized testing results to assess applicants.","zh-TW":"許多大學依賴標準化測驗結果來評估申請人。"},{"en":"Critics argue that standardized testing does not accurately reflect a student''s true potential.","zh-TW":"批評者認為標準化測驗並不能準確反映學生的真正潛力。"}]', '{"adjective":"standardized","verb":"standardize"}', NULL, 5, 6179, NULL),
(6180, 'standby', '/''stænˌbaɪ/', 'noun', '{"zh-TW":["待機狀態；候補"],"en":["ready for immediate action; also a passenger traveling on standby without a confirmed seat"]}', NULL, 'fly standby / standby ticket / on standby', '[{"en":"He flew standby and managed to get a seat on the earlier flight.","zh-TW":"他以候補方式搭機，成功拿到了更早的航班座位。"},{"en":"Budget travelers sometimes fly standby to get cheaper fares.","zh-TW":"預算有限的旅客有時以候補方式搭機，以獲得更便宜的票價。"}]', NULL, NULL, 3, 6180, NULL),
(6181, 'standby letter of credit', '/ˈstændbɑɪ ˈletər əv ˈkredɪt/', 'noun', '{"zh-TW":["備用信用證"],"en":["a bank guarantee that pays if the applicant fails to meet a contractual obligation"]}', NULL, 'issue a standby letter of credit / draw on a standby letter of credit', '[{"en":"The contractor provided a standby letter of credit as performance security.","zh-TW":"承包商提供了備用信用證作為履約保障。"},{"en":"A standby letter of credit is triggered only when the primary obligation is not met.","zh-TW":"備用信用證僅在主要義務未得到履行時才被啟動。"}]', '{"abbreviation":"SBLC"}', NULL, 5, 6181, NULL),
(6182, 'standing order', '/ˈstændɪŋ ˈɔːrdər/', 'noun', '{"zh-TW":["定期自動轉帳指令"],"en":["an instruction to a bank to make regular automatic payments"]}', NULL, 'set up a standing order / cancel a standing order', '[{"en":"She set up a standing order to pay rent on the first of each month.","zh-TW":"她設置了定期自動轉帳指令，在每月一日支付租金。"},{"en":"A standing order ensures bills are paid on time without manual action.","zh-TW":"定期轉帳指令確保帳單按時支付，無需手動操作。"}]', NULL, NULL, 5, 6182, NULL),
(6183, 'standpoint', '/ˈstændpɔɪnt/', 'noun', '{"zh-TW":["觀點；立場"],"en":["a particular attitude or way of considering something"]}', NULL, 'from a standpoint / financial standpoint / legal standpoint', '[{"en":"From a financial standpoint, the deal makes sense.","zh-TW":"從財務的角度來看，這筆交易是合理的。"},{"en":"From the customer''s standpoint, the change is positive.","zh-TW":"從客戶的角度來看，這個改變是正面的。"}]', '{"noun":"standpoint"}', NULL, 4, 6183, NULL),
(6184, 'star', '/stɑːr/', 'noun', '{"zh-TW":["明星；星星"],"en":["a famous person","a bright point of light in the sky"]}', NULL, 'star performer / five-star', '[{"en":"She is a star performer on the team.","zh-TW":"她是團隊中的明星成員。"},{"en":"We stayed at a five-star hotel.","zh-TW":"我們住在一家五星級飯店。"}]', '{"noun":"star","adjective":"star","adjective2":"stellar"}', NULL, 1, 6184, NULL),
(6185, 'starchy', '/''stɑːrtʃi/', 'adjective', '{"zh-TW":["含澱粉的；澱粉類的"],"en":["containing a lot of starch; relating to starchy foods"]}', NULL, 'starchy food / starchy vegetable / avoid starchy carbs', '[{"en":"Potatoes, rice, and bread are common starchy foods.","zh-TW":"馬鈴薯、米飯和麵包是常見的澱粉類食物。"},{"en":"Replacing starchy carbs with vegetables can help reduce calorie intake.","zh-TW":"用蔬菜替換澱粉類碳水化合物可以幫助減少卡路里攝取。"}]', '{"noun":"starch"}', NULL, 3, 6185, NULL),
(6186, 'start', '/stɑːrt/', 'verb', '{"zh-TW":["開始；創辦"],"en":["to begin","to set up a company"]}', NULL, 'start a business / from the start', '[{"en":"She started the company in her garage.","zh-TW":"她在車庫裡創辦了這家公司。"},{"en":"We knew from the start it would be difficult.","zh-TW":"我們從一開始就知道會很困難。"}]', '{"verb":"start","noun":"start","noun2":"startup","noun3":"starter"}', NULL, 2, 6186, NULL),
(6187, 'start-up costs', '/ˈstɑːrt ʌp kɒsts/', 'noun', '{"zh-TW":["啟動成本"],"en":["expenses incurred when establishing a new business or project"]}', NULL, 'estimate start-up costs / fund start-up costs', '[{"en":"Total start-up costs for the new outlet were $150000.","zh-TW":"新門市的總啟動成本為15萬元。"},{"en":"Investors typically fund start-up costs in exchange for equity.","zh-TW":"投資者通常通過提供啟動成本換取股權。"}]', NULL, NULL, 5, 6187, NULL),
(6188, 'starting capital', '/ˈstɑːrtɪŋ ˈkæpɪtəl/', 'noun', '{"zh-TW":["啟動資金；創業資本"],"en":["funds used to establish and begin operations of a new business"]}', NULL, 'raise starting capital / starting capital requirement', '[{"en":"The entrepreneur raised starting capital from family and angel investors.","zh-TW":"企業家從家人和天使投資人那裡籌集了啟動資金。"},{"en":"Starting capital is used to cover initial costs like equipment and marketing.","zh-TW":"啟動資金用於涵蓋設備和行銷等初始成本。"}]', '{"synonym":"seed capital","synonym2":"startup capital"}', NULL, 5, 6188, NULL),
(6189, 'startup', '/ˈstɑːrtʌp/', 'noun', '{"zh-TW":["新創公司"],"en":["a newly established business"]}', NULL, 'tech startup / startup culture', '[{"en":"He founded a tech startup.","zh-TW":"他創立了一家科技新創公司。"},{"en":"The startup raised millions in funding.","zh-TW":"這家新創公司籌集了數百萬資金。"}]', NULL, NULL, 3, 6189, NULL),
(6190, 'startup capital', '/ˈstɑːrtʌp ˈkæpɪtəl/', 'noun', '{"zh-TW":["創業資本"],"en":["initial funding used to establish and launch a new business"]}', NULL, 'raise startup capital / startup capital requirements', '[{"en":"The founders raised startup capital from family and angel investors.","zh-TW":"創始人從家人和天使投資者那裏籌集了創業資本。"},{"en":"Startup capital covers initial costs such as equipment, marketing, and working capital.","zh-TW":"創業資本涵蓋初始費用，如設備、行銷和營運資金。"}]', '{"synonym":"seed capital","synonym2":"seed funding"}', NULL, 5, 6190, NULL),
(6191, 'state', '/steɪt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】州；國家；狀態","【次要意義-動詞】說明；陳述；正式聲明","【次要意義-形容詞】國家的；官方的；正式的"],"en":["[primary - noun] a region or nation; a condition","[secondary - verb] to express something clearly and formally","[secondary - adjective] relating to the government or official ceremony"]}', NULL, 'state clearly / state that / state of affairs / state-of-the-art', '[{"en":"Please state your reason for requesting an extension in writing.","zh-TW":"請以書面說明您申請延期的原因。"},{"en":"The contract clearly states that all changes must be approved in advance.","zh-TW":"合約明確規定，所有變更必須事先獲得批准。"},{"en":"She stated that she had no prior knowledge of the financial irregularities.","zh-TW":"她聲明她事先不知道財務違規情況。"}]', '{"noun":"statement","adjective":"stated"}', '動詞 state = 「正式陳述/說明」，比 say 更正式，常見於合約或法律文件語境（as stated in the contract），是 TOEIC 閱讀最高頻動詞之一。', 2, 6191, NULL),
(6192, 'state of the art', '/steɪt əv ðə ɑːrt/', 'adjective', '{"zh-TW":["最先進的；最尖端的"],"en":["using the latest and most advanced techniques or technologies"]}', NULL, 'state-of-the-art technology / state-of-the-art facility', '[{"en":"The new factory uses state-of-the-art automation technology.","zh-TW":"新工廠使用了最先進的自動化技術。"},{"en":"State-of-the-art equipment reduces errors and improves output quality.","zh-TW":"最先進的設備減少了錯誤並提高了產出品質。"}]', NULL, NULL, 5, 6192, NULL),
(6193, 'stateful', '/ˈsteɪtfəl/', 'adjective', '{"zh-TW":["有狀態的"],"en":["(of an application or system) that remembers information between interactions"]}', NULL, 'stateful application / stateful protocol / stateful service', '[{"en":"Stateful applications store session information between requests.","zh-TW":"有狀態應用程式在請求之間存儲會話資訊。"},{"en":"Migrating from stateful to stateless architecture improves scalability.","zh-TW":"從有狀態遷移到無狀態架構提高了可擴展性。"}]', '{"noun":"state","antonym":"stateless"}', NULL, 3, 6193, NULL),
(6194, 'statement', '/ˈsteɪtmənt/', 'noun', '{"zh-TW":["帳單；聲明；陳述"],"en":["a document showing financial transactions over a period"]}', NULL, 'bank statement / review a statement', '[{"en":"Please review your monthly bank statement carefully.","zh-TW":"請仔細查看您的每月銀行帳單。"},{"en":"The accountant prepared a financial statement for the year.","zh-TW":"會計師準備了年度財務報表。"}]', '{"verb":"state","adjective":"stated"}', NULL, 3, 6194, 220),
(6195, 'statistic', '/stəˈtɪstɪk/', 'noun', '{"zh-TW":["統計數據；統計資料"],"en":["numerical data collected for analysis"]}', NULL, 'official statistics / statistical analysis / according to statistics', '[{"en":"Statistics show a decline in unemployment.","zh-TW":"統計數據顯示失業率下降。"},{"en":"We need statistical evidence to support the claim.","zh-TW":"我們需要統計證據來支持這項主張。"}]', '{"noun":"statistic, statistics","adjective":"statistical","adverb":"statistically"}', NULL, 3, 6195, NULL),
(6196, 'status', '/ˈsteɪtəs/', 'noun', '{"zh-TW":["地位；身分","狀態；情形"],"en":["relative social or professional position","the current situation"]}', NULL, 'status update / social status / status quo', '[{"en":"Please provide a status update on the project.","zh-TW":"請提供專案的狀態更新。"},{"en":"The company wants to maintain the status quo.","zh-TW":"公司想維持現狀。"}]', '{"noun":"status"}', NULL, 2, 6196, 221),
(6197, 'status quo', '/ˌsteɪtəs ˈkwoʊ/', 'noun', '{"zh-TW":["現狀；原有狀態"],"en":["the existing state of affairs at a particular point in time"]}', NULL, 'maintain the status quo / challenge the status quo', '[{"en":"Disrupting the status quo is necessary for meaningful change.","zh-TW":"打破現狀是實現有意義變革的必要條件。"},{"en":"Management decided to maintain the status quo until market conditions improve.","zh-TW":"管理層決定在市場條件改善之前維持現狀。"}]', NULL, NULL, 4, 6197, NULL),
(6198, 'status update', '/ˈsteɪtəs ˈʌpdeɪt/', 'noun', '{"zh-TW":["狀態更新；進度報告"],"en":["a brief report on the current state of a project or task"]}', NULL, 'provide a status update / weekly status update / status update meeting', '[{"en":"She provided a status update on the project every Friday.","zh-TW":"她每週五提供項目進度更新。"},{"en":"The client requested a daily status update during the critical phase.","zh-TW":"客戶在關鍵階段要求每日狀態更新。"}]', NULL, NULL, 5, 6198, NULL),
(6199, 'statute', '/ˈstætʃuːt/', 'noun', '{"zh-TW":["法規；法令"],"en":["a written law passed by a legislature","a written law passed by a legislative body"]}', NULL, 'statute of limitations / by statute; by statute / statute of limitations / federal statute', '[{"en":"The statute of limitations has expired.","zh-TW":"追訴時效已過。"},{"en":"It''s required by statute.","zh-TW":"這是法規要求的。"},{"en":"The regulation is required by statute.","zh-TW":"該法規是法律要求的。"},{"en":"The statute of limitations has expired.","zh-TW":"訴訟時效已過期。"}]', '{"adjective":"statutory","noun":"statute"}', NULL, 3, 6199, NULL);